import{_ as e,o as a,c as n,a2 as o}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Flow and sustainable combat rhythm","description":"","frontmatter":{},"headers":[],"relativePath":"en/game-design/combat/flow.md","filePath":"en/game-design/combat/flow.md"}'),s={name:"en/game-design/combat/flow.md"};function r(i,t,d,l,c,m){return a(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="flow-and-sustainable-combat-rhythm" tabindex="-1">Flow and sustainable combat rhythm <a class="header-anchor" href="#flow-and-sustainable-combat-rhythm" aria-label="Permalink to &quot;Flow and sustainable combat rhythm&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> Numeric examples are prototype hypotheses, not final balance. <strong>Implementation/availability:</strong> not established for these mechanics. <strong>Verification:</strong> documentation review, no playable prototype. <strong>Reviewed:</strong> 2026-10-09, Batch 05.</p><p><a href="/Syrolands-Public/en/guide/combat/flow.html">Player guide</a> · <a href="/Syrolands-Public/en/game-design/combat/overview.html">Combat foundations</a> · <a href="/Syrolands-Public/en/game-design/combat/variable-registry.html">Combat Variable Registry</a></p><h2 id="proposed-modern-only-layer" tabindex="-1">Proposed Modern-only layer <a class="header-anchor" href="#proposed-modern-only-layer" aria-label="Permalink to &quot;Proposed Modern-only layer&quot;">​</a></h2><p>Flow measures temporal spacing between consecutive <strong>valid attack/action inputs</strong>. A reasonably fast, stable rhythm may enter Flow; consistency matters more than maximum speed. Repeated instant/near-instant chaining should incur escalating trade-offs rather than become optimal damage output.</p><p>Flow must be readable, easy to understand and forgiving for normal play. It should add timing depth without making a mandatory rhythm-game gimmick or an accessibility barrier. No millisecond window, stack count or bonus is final; Batch 06 supplies Experimental test values only.</p><table tabindex="0"><thead><tr><th>Possible benefit while maintaining rhythm</th><th>Possible penalty for overly rapid chaining</th></tr></thead><tbody><tr><td>Reduced stamina cost</td><td>Escalating stamina cost</td></tr><tr><td>Recovery efficiency</td><td>Increased recovery</td></tr><tr><td>Improved accuracy/consistency</td><td>Reduced accuracy/consistency</td></tr><tr><td>Reduced handling penalty</td><td>Worse handling</td></tr><tr><td>Smoother transitions</td><td>More telegraph/commitment; temporary Flow loss/reset</td></tr></tbody></table><p>These are candidates, not a bundle of automatically granted bonuses. Shared base action numbers and a viable Legacy mode remain constraints. Any Flow benefit must be explicit, bounded and tested against opportunity costs; it is not a hidden Modern damage multiplier.</p><h2 id="prototype-alternatives" tabindex="-1">Prototype alternatives <a class="header-anchor" href="#prototype-alternatives" aria-label="Permalink to &quot;Prototype alternatives&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Candidate cadence model</th><th>What to evaluate</th></tr></thead><tbody><tr><td>Fixed windows</td><td>Clarity, forgiveness and speed-spam incentives</td></tr><tr><td>Weapon-specific bands</td><td>Slow/heavy versus fast/light rhythm without forced identical tempo</td></tr><tr><td>Adaptive/personal rhythm</td><td>Learnability, calibration abuse and stable measurement</td></tr><tr><td>Weapon-class versus action-class tracking</td><td>Mixed actions, switching and transitions</td></tr></tbody></table><p>Batch 05 left these alternatives open. For the first test only, <a href="/Syrolands-Public/en/game-design/combat/numeric-prototype.html#flow-test">Batch 06</a> selects recovery-derived rhythm, three states and bounded numerical effects. Other models are inactive alternatives. Test sustainable rhythm, interruptions and bursts of 2–3+ actions under the same stamina/recovery constraints. Invalid/repeated inputs must not count as productive rhythm; precisely which accepted action phases count, how latency is handled and how switches/pauses reset state remain Unresolved. A client-reported rhythm score cannot authorize a gameplay benefit.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><p>Entry/exit/maintenance windows; benefit/penalty magnitude; recovery floors; stamina escalation; idle/interrupt resets; invalid-input handling; mixed actions; switching modes/weapons; accessibility and remapping; latency fairness; macros/automation; feedback visibility and whether to track weapon or action classes. No state schema or new combat timer is implemented.</p>',13)])])}const u=e(s,[["render",r]]);export{p as __pageData,u as default};
